import json
import os
import tempfile

def parse_val(s):
    if s == "true":
        return True
    if s == "false":
        return False
    if s.isdigit():
        return int(s)
    return s

def fmt_val(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)

raw_json = input()
u = int(input())
updates = [input().split("=", 1) for _ in range(u)]

with tempfile.TemporaryDirectory() as tmpdir:
    path = os.path.join(tmpdir, "config.json")
    with open(path, "w", encoding="utf-8") as f:
        f.write(raw_json)
    with open(path, "r", encoding="utf-8") as f:
        cfg = json.load(f)
    for k, v in updates:
        cfg[k.strip()] = parse_val(v.strip())
    with open(path, "w", encoding="utf-8") as f:
        json.dump(cfg, f, indent=2)
    with open(path, "r", encoding="utf-8") as f:
        final_cfg = json.load(f)

for k in sorted(final_cfg):
    print(f"{k}: {fmt_val(final_cfg[k])}")

import os
import tempfile

n = int(input())
logs = [input() for _ in range(n)]

with tempfile.TemporaryDirectory() as tmpdir:
    srv_p = os.path.join(tmpdir, "server.log")
    err_p = os.path.join(tmpdir, "errors.log")
    with open(srv_p, "w", encoding="utf-8") as f:
        for line in logs:
            f.write(line + "\n")
    counts = {"INFO": 0, "WARN": 0, "ERROR": 0}
    with open(srv_p, "r", encoding="utf-8") as fin, open(err_p, "w", encoding="utf-8") as ferr:
        for raw in fin:
            line = raw.rstrip("\n")
            if line.startswith("[INFO]"):
                counts["INFO"] += 1
            elif line.startswith("[WARN]"):
                counts["WARN"] += 1
            elif line.startswith("[ERROR]"):
                counts["ERROR"] += 1
                ferr.write(line + "\n")
    with open(err_p, "r", encoding="utf-8") as f:
        errors = [l.rstrip("\n") for l in f]

print(f"INFO:{counts['INFO']} WARN:{counts['WARN']} ERROR:{counts['ERROR']}")
if not errors:
    print("NO_ERRORS")
else:
    for e in errors:
        print(e)

import json
import os
import tempfile

threshold = int(input())
n = int(input())
lines = [input() for _ in range(n)]

with tempfile.TemporaryDirectory() as tmpdir:
    log_p = os.path.join(tmpdir, "auth.log")
    inc_p = os.path.join(tmpdir, "incidents.json")
    with open(log_p, "w", encoding="utf-8") as f:
        for line in lines:
            f.write(line + "\n")
    fail_counts = {}
    with open(log_p, "r", encoding="utf-8") as f:
        for raw in f:
            s = raw.strip()
            if not s:
                continue
            ip, status, _user = s.split()
            if status == "FAIL":
                fail_counts[ip] = fail_counts.get(ip, 0) + 1
    incidents = [
        {"ip": ip, "fails": cnt}
        for ip, cnt in fail_counts.items()
        if cnt >= threshold
    ]
    incidents.sort(key=lambda x: (-x["fails"], x["ip"]))
    with open(inc_p, "w", encoding="utf-8") as f:
        json.dump(incidents, f, indent=2)
    with open(inc_p, "r", encoding="utf-8") as f:
        loaded = json.load(f)

if not loaded:
    print("CLEAN")
else:
    for item in loaded:
        print(f"{item['ip']}: {item['fails']} failed attempts")
